func (r *entityResolver) FindTodoByID(ctx context.Context, id string) (*model.Todo, error) {
	v, err := auth.ViewerFromContext(ctx)
	if err != nil {
		return nil, apperr.Unauthenticated()
	}

	tid, err := uuid.Parse(id)
	if err != nil {
		return nil, nil
	}

	t, err := r.Service.Get(ctx, tid, v.UserID)
	if err != nil {
		if errors.Is(err, service.ErrNotFound) {
			return nil, nil
		}
		return nil, apperr.Internal(r.Log, "findTodoByID", err)
	}
	return toTodoModel(t), nil
}

